"use client";

import { ChatMessages } from "@/components/chat-messages";

const CONVERSATION = [
  { id: "1", sender: "assistant" as const, content: "Hello! I'm your Nexus AI assistant. How can I help you build something amazing today?" },
  { id: "2", sender: "user" as const, content: "I want to create a beautiful landing page for my SaaS product." },
  { id: "3", sender: "assistant" as const, content: "Great choice! Nexus UI has everything you need — animated components, premium styling, and easy integration. What feature would you like to showcase first?" },
  { id: "4", sender: "user" as const, content: "I need something that will impress investors during pitch meetings." },
  { id: "5", sender: "assistant" as const, content: "Perfect. I'd recommend our Hero Aurora Spotlight combined with the Cinematic Logo Cloud. They create a stunning first impression that showcases both innovation and credibility." },
  { id: "6", sender: "user" as const, content: "Can I see how they look together?" },
  { id: "7", sender: "assistant" as const, content: "Absolutely. Click any component in the sidebar to preview it live, then copy the code directly into your project. No complex setup required." },
];

export function ChatMessagesDemo() {
  return (
    <div className="flex min-h-[580px] w-full items-center justify-center bg-gradient-to-b from-zinc-900 to-zinc-950 p-6">
      <div className="h-full w-full max-w-md">
        <ChatMessages messages={CONVERSATION} autoPlay showReplay />
      </div>
    </div>
  );
}
